class Solution {
  private int[] parent;

  private int find(int x) {
    return parent[x] == x ? x : (parent[x] = find(parent[x]));
  }

  public int numberOfComponents(int[][] properties, int k) {
    int n = properties.length;
    boolean[][] has = new boolean[n][101];
    for (int i = 0; i < n; i++) for (int v : properties[i]) has[i][v] = true;
    parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    int comps = n;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        int common = 0;
        for (int v = 1; v <= 100; v++) if (has[i][v] && has[j][v]) common++;
        if (common >= k && find(i) != find(j)) {
          parent[find(i)] = find(j);
          comps--;
        }
      }
    }
    return comps;
  }
}
